// План specs/invoices.md 2.1 / 2.2 (кейс .qa/tests/invoices/IN-03). Pre-Prod, preprod-ttp (TTP Test Locks), EN. Ничего не сохраняет.
import { test, expect } from '../../fixtures';
import { ROLE, invoiceNameRow, openNewInvoiceForm } from './invoice-helpers';

test.describe('Счета — пустой Invoice name (#dce958)', () => {
  for (const device of ['@desktop', '@android'] as const) {
    test(`New invoice without a name shows "Add name" and a pencil, no gray skeleton #dce958 ${device}`, async ({ asUser }) => {
      const page = await asUser(ROLE);
      await openNewInvoiceForm(page);
      const row = invoiceNameRow(page);
      const addName = row.getByRole('button', { name: 'Add name', exact: true });
      const pencil = row.getByRole('button').filter({ has: page.locator('svg') }).last();

      // Текст «Add name» + иконка (источник: «מה רצוי» — טקסט ברור + אייקון העריכה, בלי מלבן אפור)
      await expect(addName).toBeVisible();
      await expect(addName).toHaveClass(/text-blue-600/);
      await expect(pencil).toBeVisible();
      expect(await row.getByRole('button').count(), 'в строке две кнопки: текст и карандаш').toBe(2);
      await expect(row.locator('.animate-pulse')).toHaveCount(0);
      await expect(page.locator('.animate-pulse').filter({ visible: true }), 'скелетонов загрузки на форме не осталось').toHaveCount(0);

      // Клик по тексту → поле ввода; Escape → снова «Add name» (коммент программиста — клик по тексту или иконке)
      await addName.click();
      await expect(row.getByRole('textbox')).toBeFocused();
      await row.getByRole('textbox').press('Escape');
      await expect(addName).toBeVisible();

      // Клик по карандашу → поле ввода
      await pencil.click();
      await expect(row.getByRole('textbox')).toBeFocused();
      await row.getByRole('textbox').press('Escape');
      await expect(addName).toBeVisible();
    });
  }
});
